const cmp=(id,title,kind,cases)=>({id,title,kind,type:'compare',cases});
export const ledgers={carbon:{initial:{air:6,plants:4,animals:2,dead:2},labels:{air:'Atmospheric CO₂',plants:'Plants',animals:'Animals',dead:'Dead material'},moves:{photo:['air','plants','Photosynthesis'],feeding:['plants','animals','Feeding'],plantresp:['plants','air','Plant respiration'],animalresp:['animals','air','Animal respiration'],death:['animals','dead','Death/waste'],decomp:['dead','air','Decomposer respiration']},total:14},water:{initial:{sea:6,vapour:2,cloud:2,land:2},labels:{sea:'Sea/liquid',vapour:'Air/vapour',cloud:'Cloud droplets',land:'Land/plants'},moves:{evap:['sea','vapour','Evaporation'],condense:['vapour','cloud','Condensation'],rain:['cloud','land','Precipitation'],return:['land','sea','Runoff/groundwater'],transpire:['land','vapour','Transpiration']},total:12}};
export function transferUnit(kind,counts,key){let l=ledgers[kind],move=l?.moves[key];if(!move||!Object.keys(l.initial).every(k=>Number.isInteger(counts[k])&&counts[k]>=0)||Object.values(counts).reduce((a,b)=>a+b,0)!==l.total)throw new RangeError('Use a valid closed material account and named transfer.');if(counts[move[0]]<1)throw new RangeError('The source store is empty. Choose another possible transfer.');return{...counts,[move[0]]:counts[move[0]]-1,[move[1]]:counts[move[1]]+1};}
export function ledgerValid(kind,v){let l=ledgers[kind];return !!l&&Object.keys(l.moves).every(k=>v.observed?.includes(k))&&Object.keys(l.initial).every(k=>Number.isInteger(v.counts?.[k])&&v.counts[k]>=0)&&Object.values(v.counts||{}).reduce((a,b)=>a+b,0)===l.total&&v.reason==='matter';}
export function decayRate(temp,moisture,oxygen){if(![10,25,45].includes(Number(temp))||!['moist','dry'].includes(moisture)||!['air','low'].includes(oxygen))throw new RangeError('Choose stated model conditions.');return({10:2,25:6,45:3})[temp]*(moisture==='moist'?1:.5)*(oxygen==='air'?1:.5);}
export const compostCases=['25:moist:air','10:moist:air','25:dry:air','25:moist:low','45:moist:air'];
export const milkData={20:[180,200,220],35:[90,100,110],50:[240,260,280]};export const mean=a=>a.reduce((n,v)=>n+v,0)/a.length;
export function relativeRate(time){if(!Number.isFinite(Number(time))||Number(time)<=0||time==='')throw new RangeError('Use a positive elapsed time.');return 1/Number(time);}
export function milkPH(temp,elapsed){if(!milkData[temp]||!Number.isFinite(Number(elapsed))||Number(elapsed)<0)throw new RangeError('Choose a stated temperature and non-negative time.');return 8.8-1.6*Math.min(1,Number(elapsed)/mean(milkData[temp]));}
export function milkRunValid(v){return !!milkData[v.temp]&&v.elapsed>=mean(milkData[v.temp])&&numericEco3(v.mean,mean(milkData[v.temp]))&&numericEco3(v.rate,relativeRate(mean(milkData[v.temp])),.00001);}
export function milkValid(v){return[20,35,50].every(t=>v.observed?.includes(String(t)))&&v.interpretation==='limited';}
export function milkGraphValid(v){return v.xAxis==='temperature'&&v.yAxis==='time'&&Number(v.scale)===300&&[20,35,50].every((t,i)=>numericEco3(v.points?.[i],mean(milkData[t])));}
export const sites=[{temp:12,water:6,gas:400},{temp:16,water:5,gas:420},{temp:20,water:4,gas:440},{temp:24,water:3,gas:460}];
export const scenarios={baseline:{label:'Baseline',temp:0,water:0,gas:0},warmer:{label:'Hypothetical +4°C',temp:4,water:0,gas:0},drier:{label:'Water index −2',temp:0,water:-2,gas:0},gas:{label:'CO₂ supply index −150',temp:0,water:0,gas:-150}};
export function suitability(key){let c=scenarios[key];if(!c)throw new RangeError('Choose a stated scenario.');return sites.map(s=>{let temp=s.temp+c.temp,water=s.water+c.water,gas=s.gas+c.gas;return{temp,water,gas,suitable:temp>=10&&temp<=20&&water>=4&&gas>=300};});}
