export const tasksForEco3=k=>eco3Tasks[k];export const validEco3=(c,a)=>a!==''&&a!==null&&a!==undefined&&Number(a)===c[3];export const advanceEco3=(r,n,v)=>Number.isInteger(n)&&n>=0&&n<r.length&&r[n]===v?n+1:n;export const numericEco3=(v,a,tolerance=.001)=>v!==''&&v!==null&&v!==undefined&&Number.isFinite(Number(v))&&Math.abs(Number(v)-a)<tolerance;
